"""Context manager that adds timeout support to function calls."""

import signal
import threading
import time
from contextlib import contextmanager
from functools import wraps


class TimeoutError(Exception):
    """Raised when an operation exceeds the allowed time."""


@contextmanager
def timeout(seconds):
    """Context manager that raises TimeoutError after `seconds`.

    Uses signal.SIGALRM on Unix (main thread only) and falls back to
    a threading-based timer otherwise.

    Usage:
        with timeout(5):
            long_running_function()
    """
    if seconds <= 0:
        raise ValueError("timeout must be positive")

    # Try signal-based approach (Unix main thread only)
    if hasattr(signal, "SIGALRM") and threading.current_thread() is threading.main_thread():
        old_handler = signal.signal(signal.SIGALRM, _handler)
        signal.setitimer(signal.ITIMER_REAL, seconds)
        try:
            yield
        finally:
            signal.setitimer(signal.ITIMER_REAL, 0)
            signal.signal(signal.SIGALRM, old_handler)
    else:
        # Thread-based fallback
        timer = threading.Timer(seconds, _set_flag)
        fired = threading.Event()
        _timer_events[id(timer)] = fired
        timer.start()
        try:
            yield
        finally:
            timer.cancel()
            _timer_events.pop(id(timer), None)
            if fired.is_set():
                raise TimeoutError(f"Operation timed out after {seconds}s")


def _handler(signum, frame):
    raise TimeoutError("Operation timed out")


# Thread-based fallback state
_timer_events: dict[int, threading.Event] = {}


def _set_flag():
    # Walk all active timer events and set them (last one is the active one)
    for event in _timer_events.values():
        event.set()


def with_timeout(seconds):
    """Decorator that kills a function call after `seconds`.

    Usage:
        @with_timeout(5)
        def slow_function():
            ...
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            with timeout(seconds):
                return func(*args, **kwargs)
        return wrapper
    return decorator


# --- Examples ---

def example_basic():
    """Basic timeout usage."""
    print("--- Basic timeout example ---")
    try:
        with timeout(1):
            time.sleep(5)  # Will be interrupted
    except TimeoutError as e:
        print(f"Caught: {e}")


def example_no_timeout():
    """Operation completes within the deadline."""
    print("--- No timeout example ---")
    with timeout(3):
        result = sum(range(1000))
    print(f"Result: {result}")


def example_decorator():
    """Using the @with_timeout decorator."""
    print("--- Decorator example ---")

    @with_timeout(1)
    def fast_enough():
        return 42

    @with_timeout(0.5)
    def too_slow():
        time.sleep(5)

    print(f"fast_enough() = {fast_enough()}")
    try:
        too_slow()
    except TimeoutError as e:
        print(f"Caught: {e}")


def example_nested():
    """Nested timeouts — inner deadline wins."""
    print("--- Nested timeout example ---")
    try:
        with timeout(10):
            with timeout(1):
                time.sleep(5)
    except TimeoutError as e:
        print(f"Caught inner timeout: {e}")


# --- Tests ---

import unittest


class TestTimeout(unittest.TestCase):

    def test_raises_on_expired(self):
        with self.assertRaises(TimeoutError):
            with timeout(0.3):
                time.sleep(5)

    def test_no_raise_when_fast(self):
        with timeout(3):
            x = 1 + 1
        self.assertEqual(x, 2)

    def test_returns_value(self):
        with timeout(3):
            result = "ok"
        self.assertEqual(result, "ok")

    def test_zero_raises_valueerror(self):
        with self.assertRaises(ValueError):
            with timeout(0):
                pass

    def test_negative_raises_valueerror(self):
        with self.assertRaises(ValueError):
            with timeout(-1):
                pass

    def test_cleanup_runs_finally(self):
        cleaned = False
        try:
            with timeout(0.3):
                cleaned = True  # noqa: F841
                time.sleep(5)
        except TimeoutError:
            pass
        self.assertTrue(cleaned)

    def test_nested_inner_wins(self):
        start = time.monotonic()
        with self.assertRaises(TimeoutError):
            with timeout(10):
                with timeout(0.3):
                    time.sleep(5)
        elapsed = time.monotonic() - start
        self.assertLess(elapsed, 2)

    def test_decorator_raises(self):
        @with_timeout(0.3)
        def slow():
            time.sleep(5)

        with self.assertRaises(TimeoutError):
            slow()

    def test_decorator_returns(self):
        @with_timeout(3)
        def fast():
            return "done"

        self.assertEqual(fast(), "done")

    def test_timeout_precision(self):
        start = time.monotonic()
        with self.assertRaises(TimeoutError):
            with timeout(1):
                time.sleep(10)
        elapsed = time.monotonic() - start
        self.assertLess(abs(elapsed - 1.0), 0.5)


if __name__ == "__main__":
    example_basic()
    print()
    example_no_timeout()
    print()
    example_decorator()
    print()
    example_nested()
    print()
    print("Running tests...")
    unittest.main(verbosity=2)
